/**
 * Flag-off golden (docs/review-bounded-path-prereport-2026-11-07.md). The bounded exact path is behind an option that is absent by default; "no behaviour change when
 * off" is proved by evaluating a fixed slice of the recorded corpus and hashing every result. The golden file was generated by THIS code run on the commit BEFORE the
 * bounded path existed (origin/main at de8d68c4), so a test that reproduces its hashes shows the branch computes byte-for-byte what main computed.
 *
 * The slice is chosen to be deterministic on any machine: forced decisions, a few cheap locked yards, the first EXACT_COUNT exact-enumeration decisions with at most MAX_STATE_SPACE hidden hands (node- and
 * sample-budgeted, no wall-clock cut), and the first LADDER_COUNT ladder decisions stopped at tier 1.
 *
 * Normalization: the review-engine contract version is part of the canonical snapshot serialization, so the version string and the position hash (which is derived from it)
 * differ between the two commits by design; both are replaced by a constant before hashing. Nothing else is touched.
 *
 *   npx tsx packages/review-engine/src/devtools/generateFlagOffGolden.ts > golden.json
 */
import { fnv1a32Hex } from '@racehorse/game-core/review';
import { adaptiveEvaluateReviewPosition } from '../adaptiveEvaluateReviewPosition';
import { countCombinations } from '../combinations';
import { resolveHiddenPoolEligibility } from '../hiddenPoolEligibility';
import { replayRecordedSelfPlay } from './replayRecordedSelfPlay';

export const MAX_STATE_SPACE = 80;
export const EXACT_COUNT = 40;
export const LADDER_COUNT = 8;
export const FORCED_COUNT = 5;
export const LOCKED_COUNT = 6;

export type GoldenRow = { readonly key: string; readonly kind: 'forced' | 'locked' | 'exact' | 'ladder'; readonly hash: string; readonly length: number };

const VERSION_PATTERN = /^review-engine-v\d+$/;

function normalize(value: unknown): unknown {
  if (typeof value === 'string') return VERSION_PATTERN.test(value) ? 'review-engine-vN' : value;
  if (Array.isArray(value)) return value.map(normalize);
  if (value && typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [key, inner] of Object.entries(value)) out[key] = key === 'positionHash' ? 'position-hash' : normalize(inner);
    return out;
  }
  return value;
}

export function selectGoldenPositions(directory: string) {
  const forced: ReturnType<typeof replayRecordedSelfPlay> = [];
  const locked: ReturnType<typeof replayRecordedSelfPlay> = [];
  const exact: ReturnType<typeof replayRecordedSelfPlay> = [];
  const ladder: ReturnType<typeof replayRecordedSelfPlay> = [];
  for (const position of replayRecordedSelfPlay(directory)) {
    const { snapshot, evaluation } = position;
    if (evaluation.candidates.length <= 1) {
      if (forced.length < FORCED_COUNT) forced.push(position);
      continue;
    }
    if (snapshot.preAction.boneyard.drawableCount === 0 && snapshot.legalActions.length <= 4) {
      if (locked.length < LOCKED_COUNT) locked.push(position);
      continue;
    }
    const { eligibleForOpponent } = resolveHiddenPoolEligibility(snapshot);
    const k = snapshot.preAction.opponentTileCount;
    const space = eligibleForOpponent.length >= k ? countCombinations(eligibleForOpponent.length, k) : 0;
    if (space >= 1 && space <= MAX_STATE_SPACE) { if (exact.length < EXACT_COUNT) exact.push(position); }
    else if (space > 8_000 && ladder.length < LADDER_COUNT) ladder.push(position);
  }
  return { forced, locked, exact, ladder };
}

export function goldenRows(directory: string, options?: Parameters<typeof adaptiveEvaluateReviewPosition>[1]): GoldenRow[] {
  const { forced, locked, exact, ladder } = selectGoldenPositions(directory);
  const rows: GoldenRow[] = [];
  const run = (kind: GoldenRow['kind'], positions: typeof forced, extra: Parameters<typeof adaptiveEvaluateReviewPosition>[1]) => {
    for (const { snapshot } of positions) {
      const result = adaptiveEvaluateReviewPosition(snapshot, { phase: 'completion', ...extra, ...options });
      const json = JSON.stringify(normalize({
        evaluation: result.evaluation,
        lifecycle: result.lifecycle,
        tier: result.tier,
        evidencePolicy: result.evidencePolicy,
        feasible: result.feasible,
        estimatedStateSpace: result.estimatedStateSpace,
        convergenceReason: result.convergenceReason ?? null,
      }));
      rows.push({ key: `${snapshot.identifiers.gameId}#${snapshot.identifiers.actionNumber}`, kind, hash: fnv1a32Hex(json), length: json.length });
    }
  };
  run('forced', forced, {});
  run('locked', locked, {});
  run('exact', exact, {});
  run('ladder', ladder, { maxTier: 1 });
  return rows;
}
